import os,glob,flowio,pandas as pd,numpy as np
from scipy.stats import gaussian_kde
D=['V450-A','V525-A','B530-A','B710-A','YG586-A','YG780-A','R670-A','R780-A']
prim={'ctrl_BV421.fcs':'V450-A','ctrl_ZombieAqua.fcs':'V525-A','ctrl_FITC.fcs':'B530-A','ctrl_PerCPCy55.fcs':'B710-A','ctrl_PerCPCy55_cells.fcs':'B710-A','ctrl_PE.fcs':'YG586-A','ctrl_PECy7.fcs':'YG780-A','ctrl_PECy7_rerun.fcs':'YG780-A','ctrl_APC.fcs':'R670-A','ctrl_APCCy7.fcs':'R780-A'}

def valley(x):
 grid=np.linspace(*np.quantile(x,[.01,.99]),500)
 return grid[np.argmin(gaussian_kde(x,bw_method=.12)(grid))]

def load(fn):
 f=flowio.FlowData('/task/input/fcs/'+fn)
 return pd.DataFrame(f.as_array(),columns=['FSC-A','FSC-H','SSC-A']+D+['Time'])

for fn in sorted(prim):
 df=load(fn); p=prim[fn]; print('\n###',fn)
 for q in [.5,.6,.7,.75,.8,.85,.9,.95]:
  th=np.quantile(df[p],q); pos=df[p]>=th
  vals=np.round(df.loc[pos,D].median().to_numpy(),1)
  print(f'P>{q:.2f} th={th:9.1f} n={pos.sum():4d} med=',dict(zip(D,vals)))
 print('primary valley',valley(df[p].to_numpy()))
 # correlation of primary with every detector in upper half, and scatter medians by primary quantile bins
 bins=pd.qcut(df[p],10,labels=False,duplicates='drop')
 print('decile medians:')
 print(df.groupby(bins)[['FSC-A','FSC-H','SSC-A']+D].median().round(1).to_string())
 if fn=='ctrl_ZombieAqua.fcs':
  for vcol in ['V525-A']:
   for q in [.3,.4,.5,.6,.7,.8]:
    pos=df[vcol]>=df[vcol].quantile(q); print('zombie q',q,'n',pos.sum(),'med',df.loc[pos,D].median().round(1).to_dict())
