import pickle
import numpy as np
import pandas as pd
from scipy.stats import trim_mean
D=['V450-A','V525-A','B530-A','B710-A','YG586-A','YG780-A','R670-A','R780-A']
beads={'ctrl_BV421.fcs':'V450-A','ctrl_FITC.fcs':'B530-A','ctrl_PE.fcs':'YG586-A','ctrl_PECy7.fcs':'YG780-A','ctrl_PECy7_rerun.fcs':'YG780-A','ctrl_APC.fcs':'R670-A','ctrl_APCCy7.fcs':'R780-A'}
with open('/tmp/all_fcs.pkl','rb') as h:
    x=pickle.load(h)
for fn,p in beads.items():
    d=x[fn]
    order=np.argsort(d[p].to_numpy(),kind='stable')
    neg_idx=order[:len(d)//2]
    pos_idx=order[-len(d)//2:]
    out={}
    for method in ['mean','median','trim10']:
        vals=[]
        for c in D:
            if c==p:
                vals.append(1.0); continue
            if method=='mean':
                num=d.loc[pos_idx,c].mean()-d.loc[neg_idx,c].mean(); den=d.loc[pos_idx,p].mean()-d.loc[neg_idx,p].mean()
            elif method=='median':
                num=d.loc[pos_idx,c].median()-d.loc[neg_idx,c].median(); den=d.loc[pos_idx,p].median()-d.loc[neg_idx,p].median()
            else:
                num=trim_mean(d.loc[pos_idx,c],.1)-trim_mean(d.loc[neg_idx,c],.1); den=trim_mean(d.loc[pos_idx,p],.1)-trim_mean(d.loc[neg_idx,p],.1)
            vals.append(num/den)
        out[method]=vals
    print('\n',fn)
    for method,v in out.items(): print(method,' '.join(f'{z:.6f}' for z in v))
